// Regenerates emoji.js from emojibase-data (MIT): `node editor/vendor/emoji.gen.mjs`.
// Keeps emoji, Korean label and tags per picker group; skips skin-tone components and emoji newer
// than 15.0, which Windows fonts still draw as boxes.
import { readFileSync, writeFileSync } from 'node:fs'

const data = JSON.parse(readFileSync(new URL('../../node_modules/emojibase-data/ko/data.json', import.meta.url), 'utf8'))
const GROUPS = [
  ['스마일리 및 사람', '😊', [0, 1]],
  ['동물 및 자연', '🐱', [3]],
  ['음식 및 음료', '🍔', [4]],
  ['여행 및 장소', '🚌', [5]],
  ['활동', '⚽', [6]],
  ['사물', '💡', [7]],
  ['기호', '🔣', [8]],
  ['깃발', '🏳️', [9]]
]
const out = GROUPS.map(([name, icon, ids]) => [
  name,
  icon,
  data
    .filter((e) => ids.includes(e.group) && e.version <= 15)
    .sort((a, b) => a.order - b.order)
    // emojibase adds U+FE0F even after default-emoji characters (👍️); drop it so notes get the plain form.
    .map((e) => [e.emoji.replace(/(\p{Emoji_Presentation})️/gu, '$1'), e.label, ...(e.tags ?? [])].join('\t').replace(/\n/g, ' '))
    .join('\n')
])
writeFileSync(
  new URL('./emoji.js', import.meta.url),
  `// Generated by emoji.gen.mjs from emojibase-data (MIT). Do not edit.\n` +
    `// [group, tab icon, "emoji\\tlabel\\ttag..." lines]\n` +
    `export const GROUPS = ${JSON.stringify(out)}\n`
)
